sources.main.cod:
using symbol "std:io" @print;
using symbol "std:io" @assert;
using units "/ws/EvtWorks/cod-project/tests/cod/language/pool-interface.cod" {Slot};
using "/ws/EvtWorks/cod-project/tests/cod/language/pool-interface.cod" (==);
using "/ws/EvtWorks/cod-project/tests/cod/language/pool-adapter.cod" Pool;
using "/ws/EvtWorks/cod-project/tests/cod/language/pool-adapter.cod" replace as replace_pool;
using "/ws/EvtWorks/cod-project/tests/cod/language/pool-adapter.cod" peek as peek_pool;
using "adapter.cod" Single;
using "adapter.cod" replace as replace_single;
using "adapter.cod" peek as peek_single;
using "adapter.cod" locate as locate_single;
symbol @arena::region;
effect @arena <- region(4096u64);
{
  let pool = create(@arena, 2u32);
  acquire(pool, 7);
  acquire(pool, 11);
  let single = create_single(@arena);
  let occupied = used_bytes(@arena);
  behave @assert(replace_pool(pool, Slot(1u32), 13) == Slot(1u32));
  behave @assert(replace_single(single, Slot(0u32), 6) == Slot(0u32));
  behave @print(peek_pool(pool, Slot(1u32)));
  behave @print(peek_single(single, Slot(0u32)));
  store(locate_single(single, Slot(0u32)), 9);
  behave @print(peek_single(single, Slot(0u32)));
  behave @print(peek_pool(pool, Slot(1u32)));
  behave @assert(used_bytes(@arena) == occupied);
};

